const app = express();
app.use(express.json({ limit: '2mb' }));

const PORT = Number(process.env.MOCK_MCP_PORT || 8877);

app.get('/health', (_req, res) => {
  res.json({ ok: true, service: 'mock-jlc-mcp-adapter', port: PORT });
});

app.post('/', (req, res) => {
  const { action, payload } = req.body || {};
  if (action !== 'native-project.generate') {
    return res.status(400).json({ ok: false, error: `Unsupported action: ${action}` });
  }

  const projectName = payload?.name || 'unnamed-native-project';
  const projectId = payload?.project_id || projectName.toLowerCase().replace(/[^a-z0-9]+/g, '');
  const outline = payload?.outline || {};

  res.json({
    ok: true,
    adapter: 'mock-jlc-mcp-adapter',
    result: {
      projectName,
      projectId,
      outline,
      mode: 'mock-http-adapter',
      message: 'Mock MCP adapter accepted native-project.generate.'
    }
  });
});

app.listen(PORT, () => {
  console.log(`mock-jlc-mcp-adapter listening on http://127.0.0.1:${PORT}`);
});
"}

